#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// One CTA per "row" (i.e. per batch element). Each row has M = features*dim1*dim2
// contiguous elements. We compute mean/var over the whole row via a block-wide
// reduction, then apply the elementwise affine transform (gamma/beta have the
// same shape as a row, so this is NOT a broadcast over spatial dims - it's a
// full elementwise affine, matching nn.LayerNorm semantics with
// normalized_shape == (features, dim1, dim2)).
__global__ void layernorm_kernel_f32(
    const float* __restrict__ X,
    const float* __restrict__ G,
    const float* __restrict__ Bb,
    float* __restrict__ Y,
    int64_t M,
    float eps)
{
  extern __shared__ float sdata[];

  const int n = blockIdx.x;
  const float* x_row = X + (int64_t)n * M;
  float* y_row = Y + (int64_t)n * M;

  const int tid = threadIdx.x;
  const int nthreads = blockDim.x;

  const bool vec_ok = ((M & 3) == 0);
  const int64_t M4 = M >> 2;
  float sum = 0.f;
  if (vec_ok) {
    Tensor mX4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(x_row)),
                              make_shape(M4), make_stride(Int<1>{}));
    for (int64_t i = tid; i < M4; i += nthreads) {
      float4 v4 = mX4(i);
      sum += v4.x + v4.y + v4.z + v4.w;
    }
  } else {
    Tensor mX = make_tensor(make_gmem_ptr(x_row), make_shape(M), make_stride(Int<1>{}));
    for (int64_t i = tid; i < M; i += nthreads) {
      float v = mX(i);
      sum += v;
    }
  }
  float* s_sum = sdata;
  s_sum[tid] = sum;
  __syncthreads();
  for (int offset = nthreads / 2; offset > 0; offset >>= 1) {
    if (tid < offset) {
      s_sum[tid] += s_sum[tid + offset];
    }
    __syncthreads();
  }
  __shared__ float mean_s;
  if (tid == 0) {
    mean_s = s_sum[0] / (float)M;
  }
  __syncthreads();
  const float mean = mean_s;
  float sumsq = 0.f;
  if (vec_ok) {
    Tensor mX4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(x_row)),
                              make_shape(M4), make_stride(Int<1>{}));
    for (int64_t i = tid; i < M4; i += nthreads) {
      float4 v4 = mX4(i);
      float dx = v4.x - mean;
      float dy = v4.y - mean;
      float dz = v4.z - mean;
      float dw = v4.w - mean;
      sumsq += dx * dx + dy * dy + dz * dz + dw * dw;
    }
  } else {
    Tensor mX = make_tensor(make_gmem_ptr(x_row), make_shape(M), make_stride(Int<1>{}));
    for (int64_t i = tid; i < M; i += nthreads) {
      float v = mX(i);
      float d = v - mean;
      sumsq += d * d;
    }
  }
  __syncthreads();
  float* s_sumsq = sdata;
  s_sumsq[tid] = sumsq;
  __syncthreads();
  for (int offset = nthreads / 2; offset > 0; offset >>= 1) {
    if (tid < offset) {
      s_sumsq[tid] += s_sumsq[tid + offset];
    }
    __syncthreads();
  }
  __shared__ float rstd_s;
  if (tid == 0) {
    float var = s_sumsq[0] / (float)M;
    if (var < 0.f) var = 0.f;
    rstd_s = rsqrtf(var + eps);
  }
  __syncthreads();
  const float rstd = rstd_s;

  if (vec_ok) {
    Tensor mX4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(x_row)),
                              make_shape(M4), make_stride(Int<1>{}));
    Tensor mG4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(G)),
                              make_shape(M4), make_stride(Int<1>{}));
    Tensor mB4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(Bb)),
                              make_shape(M4), make_stride(Int<1>{}));
    Tensor mY4 = make_tensor(make_gmem_ptr(reinterpret_cast<float4*>(y_row)),
                              make_shape(M4), make_stride(Int<1>{}));
    for (int64_t i = tid; i < M4; i += nthreads) {
      float4 v = mX4(i);
      float4 g = mG4(i);
      float4 b = mB4(i);
      float4 out;
      out.x = (v.x - mean) * rstd * g.x + b.x;
      out.y = (v.y - mean) * rstd * g.y + b.y;
      out.z = (v.z - mean) * rstd * g.z + b.z;
      out.w = (v.w - mean) * rstd * g.w + b.w;
      mY4(i) = out;
    }
  } else {
    Tensor mX = make_tensor(make_gmem_ptr(x_row), make_shape(M), make_stride(Int<1>{}));
    Tensor mG = make_tensor(make_gmem_ptr(G), make_shape(M), make_stride(Int<1>{}));
    Tensor mB = make_tensor(make_gmem_ptr(Bb), make_shape(M), make_stride(Int<1>{}));
    Tensor mY = make_tensor(make_gmem_ptr(y_row), make_shape(M), make_stride(Int<1>{}));
    for (int64_t i = tid; i < M; i += nthreads) {
      float v = mX(i);
      float g = mG(i);
      float b = mB(i);
      mY(i) = (v - mean) * rstd * g + b;
    }
  }
}

torch::Tensor cute_layernorm_forward(torch::Tensor x,
                                      torch::Tensor weight,
                                      torch::Tensor bias,
                                      double eps) {
